#!/usr/bin/env node
// Arbiter hook: fail-closed completion backstop (#1212, INV-114)
// Hook type: Stop — fires when the agent finishes responding
// Hard block (exit 2) — prevents the stop and returns stderr to the model
// On every working branch with phase != complete, a completion claim in the
// final assistant message requires THREE correlated evidence artifacts, all
// bound to the current branch + HEAD sha. Missing or stale → block.
// Generated by arbiter for project: arbiter
import { readTaskState, getRepoRoot, sanitizeTaskId } from './lib.mjs'
import { spawnSync } from 'node:child_process'
import { readFileSync, readdirSync, existsSync } from 'node:fs'
import { join } from 'node:path'

// The shared verifier is loaded lazily and fail-CLOSED: a static import that
// cannot resolve would abort the hook with exit 1, which Claude Code treats as
// non-blocking — the completion backstop would go silent instead of blocking.
let gateEvidence = null
try {
  gateEvidence = await import('../../scripts/lib/gate-evidence.mjs')
} catch {
  gateEvidence = null
}

function main() {
  // --- stdin (Stop event payload) -------------------------------------------
  let input = {}
  try {
    input = JSON.parse(readFileSync(0, 'utf-8')) ?? {}
  } catch {
    // Unreadable/non-JSON stdin is not something we can correlate against — the
    // guard only ever blocks on a *detected* completion claim, so stand down.
    process.exit(0)
  }

  // Re-entry guard: exit 2 re-prompts the model with this hook still active. If we
  // fired again we would loop forever, so always allow the stop on re-entry.
  if (input.stop_hook_active === true) process.exit(0)

  const root = getRepoRoot()

  const git = (args) => spawnSync('git', args, { cwd: root, encoding: 'utf-8' })
  const gitLine = (args) => {
    const r = git(args)
    return r.status === 0 ? String(r.stdout).trim() : ''
  }

  // Explicit save refs carry incomplete snapshots and are the only branches where
  // completion enforcement stands down. Main/trunk-solo and ordinary work branches
  // remain governed.
  const branch = gitLine(['rev-parse', '--abbrev-ref', 'HEAD'])
  if (/^(?:backup|preserve|wip)\//.test(branch)) process.exit(0)

  // Only guard for an active, not-yet-complete task.
  const { phase, taskId } = readTaskState(root)
  if (phase === 'complete' || phase === 'unknown') process.exit(0)

  // Only guard when the final assistant message claims completion.
  const claimText = latestAssistantText(input.transcript_path)
  if (claimText === null) process.exit(0) // missing/unreadable transcript → stand down
  const COMPLETION_PATTERNS =
    /\b(task (is )?(complete|completed|done|finished)|task complete|task completed|all phases complete|work is (done|complete)|implementation (is )?(complete|done|finished)|pr merged|merged to main|wrapping up|ready to (merge|close)|shipped)\b/i
  if (!COMPLETION_PATTERNS.test(claimText)) {
    // #1402 — end-of-task reflection sweep: a non-blocking nudge to drain seen-but-unrecorded
    // findings. Only fires when undrained findings exist; never changes the exit code.
    reflectionSweep(root)
    process.exit(0)
  }

  // --- completion claimed: require correlated evidence ----------------------
  const fail = (reason) => {
    process.stderr.write(
      `━━━ STOP EVIDENCE GUARD ━━━\n` +
        `Completion claim blocked on ${branch} (phase: ${phase}):\n` +
        `  ${reason}\n\n` +
        `A completion claim requires plan-review + dispatch + gate-pass evidence,\n` +
        `each recorded on this branch at a commit reachable from HEAD.\n` +
        `Re-run the missing step, then claim completion again.\n` +
        `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`,
    )
    process.exit(2)
  }

  const readJson = (path) => {
    try {
      return JSON.parse(readFileSync(path, 'utf-8'))
    } catch {
      return null
    }
  }

  // exit 0 = ancestor-or-equal; anything else (incl. bad sha error) = uncorrelated.
  const isAncestor = (sha) => {
    if (typeof sha !== 'string' || sha.length === 0) return false
    return git(['merge-base', '--is-ancestor', sha, 'HEAD']).status === 0
  }

  // 1. plan-review — verdict PASS, on this branch, sha is an ancestor of HEAD.
  const planPath = join(
    root,
    '.arbiter',
    'evidence',
    'plan-review',
    sanitizeTaskId(taskId),
    'latest.json',
  )
  const plan = readJson(planPath)
  if (plan === null) fail('plan-review evidence missing or unreadable (latest.json)')
  if (plan.verdict !== 'PASS')
    fail(`plan-review verdict is ${JSON.stringify(plan.verdict)} — must be PASS`)
  if (plan.branch !== branch)
    fail(`plan-review evidence is for branch ${JSON.stringify(plan.branch)}, not ${branch}`)
  if (!isAncestor(plan.sha)) fail('plan-review evidence sha is not an ancestor of HEAD (stale)')

  // 2. dispatch sidecar — review agents dispatched on this branch, ancestor of HEAD.
  const dispatch = readJson(join(root, '.arbiter', 'agents-dispatched.json'))
  if (dispatch === null) fail('dispatch evidence missing (.arbiter/agents-dispatched.json)')
  if (dispatch.branch !== branch)
    fail(`dispatch evidence is for branch ${JSON.stringify(dispatch.branch)}, not ${branch}`)
  if (!isAncestor(dispatch.sha)) fail('dispatch evidence sha is not an ancestor of HEAD (stale)')

  // 3. gate-pass — strict: THIS tree, in THIS checkout, under THIS toolchain, was
  // verified recently enough. The full identity binding replaces the old
  // branch+head_sha pair; #1441 anti-replay rides along as the task-id axis.
  const gatePath = join(root, '.arbiter', 'gate-pass.json')
  if (!existsSync(gatePath)) fail('gate-pass evidence missing (.arbiter/gate-pass.json)')
  if (gateEvidence === null)
    fail(
      'gate-pass verifier unavailable (scripts/lib/gate-evidence.mjs) — evidence cannot be bound to this tree',
    )
  const gateVerdict = gateEvidence.verifyGateEvidenceFile(gatePath, {
    root,
    minLevel: 'L2',
    maxAgeMin:
      Number(process.env.ARBITER_EVIDENCE_MAX_AGE_MIN) ||
      gateEvidence.GATE_EVIDENCE_DEFAULT_TTL_MIN,
    taskId,
  })
  if (!gateVerdict.ok) fail(gateVerdict.reason)

  // All correlated evidence present — allow the stop, after a final reflection-sweep nudge (#1402).
  reflectionSweep(root)
  process.exit(0)
}

/**
 * #1402 — count undrained findings across `.arbiter/findings/*.jsonl` and, when any exist, emit a
 * non-blocking nudge to drain them with `arbiter note`/review. Never throws (best-effort), never
 * changes the exit code — it only writes advisory text to stderr (visible to the model).
 */
function reflectionSweep(root) {
  try {
    const fd = join(root, '.arbiter', 'findings')
    if (!existsSync(fd)) return
    let count = 0
    for (const f of readdirSync(fd)) {
      if (!f.endsWith('.jsonl')) continue
      const raw = readFileSync(join(fd, f), 'utf-8')
      count += raw.split('\n').filter((l) => l.trim().length > 0).length
    }
    if (count === 0) return
    process.stderr.write(
      `[arbiter] REFLECTION SWEEP: ${count} undrained finding${count === 1 ? '' : 's'} in .arbiter/findings/.\n` +
        `Capture anything seen-but-unrecorded with \`arbiter note\`, then review/drain the spool before wrapping up.\n`,
    )
  } catch {
    // Best-effort nudge — never block the stop on a sweep failure.
  }
}

/** Concatenated text of the last assistant message, or null if unreadable. */
function latestAssistantText(transcriptPath) {
  if (typeof transcriptPath !== 'string' || transcriptPath.length === 0) return null
  let raw
  try {
    raw = readFileSync(transcriptPath, 'utf-8')
  } catch {
    return null
  }
  let last = null
  for (const line of raw.split('\n')) {
    const trimmed = line.trim()
    if (trimmed.length === 0) continue
    let obj
    try {
      obj = JSON.parse(trimmed)
    } catch {
      continue // skip a partially-written trailing line
    }
    if (obj && obj.type === 'assistant') last = obj
  }
  if (last === null) return null
  const content = last.message && Array.isArray(last.message.content) ? last.message.content : []
  return content
    .filter((b) => b && b.type === 'text' && typeof b.text === 'string')
    .map((b) => b.text)
    .join('\n')
}

// Fail-visible backstop: an *unexpected* crash exits 1 (a non-blocking Stop-hook
// notice — the agent can still stop, but the failure is surfaced, never swallowed).
// Deliberate exit(0)/exit(2) decisions inside main() are unaffected.
try {
  main()
} catch (err) {
  process.stderr.write(
    `[stop-evidence-guard] unexpected error: ${err?.message ?? err} — allowing stop\n`,
  )
  process.exit(1)
}
